def north_chart(points):
    p=np.asarray(points,float)
    if p.ndim!=2 or p.shape[1]!=3 or not np.isfinite(p).all() or not np.allclose(np.linalg.norm(p,axis=1),1,atol=1e-8,rtol=0):
        raise ValueError("Expected finite unit sphere rows.")
    den=1-p[:,2]
    if np.any(den<=1e-12):raise ValueError("North pole excluded or too close.")
    return p[:,:2]/den[:,None]

def inverse_north(coordinates):
    a=np.asarray(coordinates,float)
    if a.ndim!=2 or a.shape[1]!=2 or not np.isfinite(a).all():raise ValueError("Expected finite N by 2 coordinates.")
    q=np.sum(a*a,axis=1)
    return np.column_stack([2*a[:,0]/(1+q),2*a[:,1]/(1+q),(q-1)/(q+1)])

def tangent_projection(point, vector):
    p=np.asarray(point,float);v=np.asarray(vector,float)
    if p.shape!=(3,) or v.shape!=(3,) or not np.isfinite(p).all() or not np.isfinite(v).all() or not np.isclose(p@p,1):raise ValueError("Unit point and finite 3-vector required.")
    return v-p*(p@v)

def backproject_z(pixels, depths, intrinsics):
    uv=np.asarray(pixels,float);z=np.asarray(depths,float);K=np.asarray(intrinsics,float)
    if uv.ndim!=2 or uv.shape[1]!=2 or z.shape!=(len(uv),) or not np.isfinite(uv).all() or not np.isfinite(z).all() or np.any(z<=0):raise ValueError("Finite pixels and positive Z required.")
    rays=np.column_stack([uv,np.ones(len(uv))])@np.linalg.inv(K).T
    if np.any(np.abs(rays[:,2])<1e-12):raise ValueError("Invalid ray normalization.")
    return rays*(z/rays[:,2])[:,None]

def proper_rotation(matrix, atol=1e-8):
    R=np.asarray(matrix,float)
    return bool(R.shape==(3,3) and np.isfinite(R).all() and np.allclose(R.T@R,np.eye(3),atol=atol,rtol=0) and np.isclose(np.linalg.det(R),1,atol=atol,rtol=0))

def error_and_coverage(predicted, reference):
    p=np.asarray(predicted,float);r=np.asarray(reference,float)
    if p.shape!=r.shape:raise ValueError("Shapes must match.")
    eligible=np.isfinite(r);valid=eligible&np.isfinite(p)
    return {"mae":float(np.mean(abs(p[valid]-r[valid]))) if valid.any() else None,
            "coverage":float(valid.sum()/eligible.sum()) if eligible.any() else None}

def conditional_depth_sd(disparity, focal, baseline, offset, disparity_sd):
    if disparity+offset<=0 or disparity_sd<0:raise ValueError("Positive denominator and nonnegative SD required.")
    return focal*baseline/(disparity+offset)**2*disparity_sd

def stable_softmax(scores):
    s=np.asarray(scores,float)
    if s.ndim!=2 or not s.shape[0] or not s.shape[1] or not np.isfinite(s).all():raise ValueError("Finite nonempty matrix required.")
    e=np.exp(s-s.max(axis=1,keepdims=True))
    return e/e.sum(axis=1,keepdims=True)

def same_frame_mask(frame_ids):
    ids=np.asarray(frame_ids)
    if ids.ndim!=1:raise ValueError("One-dimensional IDs required.")
    return ids[:,None]==ids[None,:]

def weighted_values(weights, values):
    W=np.asarray(weights,float);V=np.asarray(values,float)
    if W.ndim!=2 or V.ndim!=2 or W.shape[1]!=V.shape[0] or not np.isfinite(W).all() or not np.isfinite(V).all() or np.any(W<0) or not np.allclose(W.sum(1),1):raise ValueError("Compatible normalized weights required.")
    return W@V

def apply_similarity(points, scale, rotation, translation):
    if not np.isfinite(scale) or scale<=0:raise ValueError("Positive finite scale required.")
    return scale*np.asarray(points,float)@np.asarray(rotation,float).T+np.asarray(translation,float)

def paired_rmse(predicted, reference):
    p=np.asarray(predicted,float);r=np.asarray(reference,float)
    if p.shape!=r.shape or p.ndim!=2 or p.shape[1]!=3 or not len(p) or not np.isfinite(p).all() or not np.isfinite(r).all():raise ValueError("Finite nonempty corresponding Nx3 tables required.")
    return float(np.sqrt(np.mean(np.sum((p-r)**2,axis=1))))

def split_is_disjoint(anchor_ids, evaluation_ids):
    a=list(anchor_ids);b=list(evaluation_ids)
    return len(a)==len(set(a)) and len(b)==len(set(b)) and not (set(a)&set(b))

def fifo_age(arrivals, service_times):
    a=np.asarray(arrivals,float);s=np.asarray(service_times,float)
    if a.ndim!=1 or a.shape!=s.shape or not np.isfinite(a).all() or not np.isfinite(s).all() or np.any(np.diff(a)<=0) or np.any(s<0):raise ValueError("Ordered arrivals and nonnegative times required.")
    finish=-np.inf;out=[]
    for t,d in zip(a,s):
        finish=max(finish,t)+d;out.append(finish-t)
    return np.asarray(out)

def latency_quantiles(latencies):
    x=np.asarray(latencies,float)
    if x.ndim!=1 or not len(x) or not np.isfinite(x).all() or np.any(x<0):raise ValueError("Finite nonnegative nonempty vector required.")
    return {"p50":float(np.quantile(x,.5)),"p95":float(np.quantile(x,.95))}

def decision_delay(onset_time, decision_time):
    if not np.isfinite([onset_time,decision_time]).all() or decision_time<onset_time:raise ValueError("Decision must be finite and no earlier than onset.")
    return decision_time-onset_time

